(* [comment removed for export] *)
Lemma stream_ctor_close_ioworld3 : forall LB m (ioc bs allocb regb cfgb schedb v q stb va : Z) (F : fbv) (ds : list byte),
  rw_cells rsegs m ioc (IoCtxCells allocb regb schedb) ->
  rw_cells rsegs m bs (BasicStreamCells stb) ->
  AllocImpl LB m allocb -> Registry LB m regb ioc v 0 -> ConfigSvc LB m cfgb (cfg_hdr ioc) ->
  Scheduler LB m schedb (mkSCH (sched_hdr ioc cfgb) 0 0 0) ->
  StreamSvc LB m v (ssvc_hdr ioc schedb) q -> ImplBlock LB m q (impl_after va stb) ->
  StateBlock LB m stb ioc q (st_closed (mkST (mkSPC VP_SPCI_STATE 1 1 1) 0 F STREAM_OK 0 0)) ds ->
  IoWorld3 LB m ioc bs allocb regb cfgb schedb v q stb F ds STREAM_EOF 0 0.
Proof.
  intros LB m ioc bs allocb regb cfgb schedb v q stb va F ds IOC BS AI REG CFG SCH SSVC IMPL SB.
  unfold IoWorld3, ImplBlockV. unfold cfg_hdr, sched_hdr, ssvc_hdr, impl_after, st_closed in *. cbn [st_hdr st_fb st_nread st_nread_bytes] in SB.
  repeat (split; [assumption|]). split; [exists va; exact IMPL| exact SB].
Qed.

